import hashlib, re
from pathlib import Path
root = Path(r'c:/Users/valtt/OneDrive/Godot/AXEL/axel_project')
# collect text references to res:// paths and bare filenames
ref_text = []
for p in root.rglob('*'):
    if p.is_file() and p.suffix in {'.gd','.tscn','.tres','.godot','.cfg','.md','.py','.json','.shader','.gdshader'}:
        try:
            ref_text.append(p.read_text(encoding='utf-8', errors='ignore'))
        except Exception:
            pass
blob = '\n'.join(ref_text)
# candidate asset extensions
asset_exts = {'.png','.jpg','.jpeg','.webp','.svg','.ttf','.wav','.ogg'}
assets = [p for p in root.rglob('*') if p.is_file() and p.suffix.lower() in asset_exts and '.godot' not in p.parts]
# hash pngs only for exact dupes
from collections import defaultdict
by_hash = defaultdict(list)
for p in assets:
    if p.suffix.lower() == '.png':
        h = hashlib.sha256(p.read_bytes()).digest()
        by_hash[h].append(p)
exact_dupes = {h:ps for h,ps in by_hash.items() if len(ps)>1}
print('EXACT_PNG_DUPLICATE_GROUPS', len(exact_dupes))
for h, ps in sorted(exact_dupes.items(), key=lambda x: str(x[1][0])):
    print('---')
    for p in ps:
        print(p.relative_to(root).as_posix())
# unused pngs (no path substring reference)
unused=[]
for p in assets:
    if p.suffix.lower() != '.png':
        continue
    rel = p.relative_to(root).as_posix()
    res = 'res://' + rel
    name = p.name
    if res not in blob and rel not in blob and name not in blob:
        unused.append(rel)
print('UNREFERENCED_PNG_COUNT', len(unused))
for u in sorted(unused)[:40]:
    print('UNUSED', u)
"

